using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class ActualRelabelChartsDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Transport both relabel factors through the actual charts.",
        H("Transport both relabel factors through the actual charts"),
        Blocks(
            Paragraph(Text("countedInCharts composes cG, r and cH.symm on both vertices and numbered edges. charted_weight transports the two row matrices together through these charts. It does not infer invariance of an individual edge value under an arbitrary basis change. The literal forward factor uses reindex r.vertex, and the backward factor uses timeMap G after the inverse reindexing.")),
            Paragraph(Text("The Charts section quantifies V,E,W,J with Fintype instances, DecidableEq V and W, graphs G,H, dimensions n,m and count matrices A,B. Each weight theorem takes d and NeZero d; residue comparisons also take 3 ∣ d. presentation_relabel_residue uses the chosen chart F and chart H. chart_forward_residue retains the next chart phase, and chart_backward_residue retains the negative old chart phase. positive_leaf_residue keeps both chart corrections and the original nonnegative middle factors R,S.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrelabelcharts-counted-in-charts"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.countedInCharts"), H("countedInCharts"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Literally cH^{-1} after r after cG, on vertices AND numbered edges."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrelabelcharts-charted-weight"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.charted_weight"), H("charted_weight"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Transport the forward and backward row factors together through the actual old and new charts. Their weight equals that of the composed counted relabel for every nonzero period."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrelabelcharts-positive-leaf-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.positive_leaf_residue"), H("positive_leaf_residue"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Immediate actual positive-leaf specialization with BOTH chart terms. The nonnegative middle factors are the original R,S."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-compose"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.compose"), H("compose"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Compose both vertex and edge equivalences and their endpoint laws. The resulting graph relabel is used to form the literal counted chart composite.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-identity-relabel"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.identityRelabel"), H("identityRelabel"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Use identity equivalences on the vertices and numbered edges of a counted graph. This supplies the standard chart without introducing another enumeration.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-charted-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.charted_residue"), H("charted_residue"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For nonzero periods divisible by three, apply the actual counted relabel comparison after transporting both factors through the charts. The result retains the phase of that complete composite.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-identity-basis"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.identity_basis"), H("identity_basis"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The identity vertex reindexing leaves the standard coefficient basis unchanged. This removes an identity chart in the positive-leaf comparison.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-presentation-relabel-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.presentation_relabel_residue"), H("presentation_relabel_residue"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Actual arbitrary-presentation relabel leaf, in P1's chosen two charts.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-chart-forward-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.chart_forward_residue"), H("chart_forward_residue"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The next correction uses the real counted composite chart(F)^{-1} r.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelcharts-chart-backward-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelCharts.chart_backward_residue"), H("chart_backward_residue"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The old^{-1} correction has the literal opposite phase. Neither chart term is erased, even when the chart preserves beam action.")))))));
}
